{
  "explanation": "Anita leaves at 10:30, so both the loading team and drivers for Route C are unavailable when the van returns, causing the van to be late and Route C to miss delivery.",
  "fixes": [
    {
      "id": "fix-1-extend-anita",
      "description": "Extend Anita's availability so she can stay for the loading of Route C.",
      "operations": [
        {
          "op": "set_person_availability",
          "target_id": "person-anita",
          "field": "available_until",
          "value": 660
        }
      ]
    },
    {
      "id": "fix-2-add-driver-ravi-to-c",
      "description": "Add Ravi as an additional driver for Route C so the route can be driven even if Anita departs early.",
      "operations": [
        {
          "op": "add_driver",
          "target_id": "route-c",
          "field": "driver_ids",
          "value": "person-ravi"
        }
      ]
    },
    {
      "id": "fix-3-use-car-for-route-c",
      "description": "Assign the Car to Route C (instead of the Van) and give the Van to Route B, avoiding the late‑return conflict.",
      "operations": [
        {
          "op": "move_route",
          "target_id": "route-c",
          "field": "vehicle_id",
          "value": "vehicle-car"
        },
        {
          "op": "move_route",
          "target_id": "route-b",
          "field": "vehicle_id",
          "value": "vehicle-van"
        }
      ]
    }
  ]
}

